mapper.update:
UPDATE workitem SET title = #{title}, content_md = #{contentMd},
    version = version + 1, modifier_id = #{modifierId}
WHERE id = #{id} AND tenant_id = #{tenantId} AND version = #{version} AND is_deleted = 0

UPDATE workitem SET title = #{title}, content_md = #{contentMd}, priority = #{priority},
    version = version + 1, modifier_id = #{modifierId}
WHERE id = #{id} AND tenant_id = #{tenantId} AND version = #{version} AND is_deleted = 0

UPDATE workitem SET is_deleted = 1, deleted_at = NOW(3),
    version = version + 1, modifier_id = #{modifierId}
WHERE id = #{id} AND tenant_id = #{tenantId} AND version = #{version} AND is_deleted = 0

